#[derive(Debug, Clone, PartialEq)]
pub struct BiomeCappedSurface {
    pub floor_blocks: Vec<i32>,
    pub ceiling_blocks: Vec<i32>,
    pub sea_block: Option<u32>,
    pub foundation_block: Option<u32>,
    pub beach_block: Option<u32>,
}
impl BiomeCappedSurface {
    pub fn read(r: &mut &[u8]) -> Result<Self> {
        let f_floor_blocks = (|| -> Result<_> {
            Ok({
                let n = to_len(read_varint(r)?)?;
                let mut v = Vec::with_capacity(cap(n, r));
                for _ in 0..n {
                    v.push(read_li32(r)?);
                }
                v
            })
        })()
        .map_err(|e| e.at("BiomeCappedSurface.floor_blocks"))?;
        let f_ceiling_blocks = (|| -> Result<_> {
            Ok({
                let n = to_len(read_varint(r)?)?;
                let mut v = Vec::with_capacity(cap(n, r));
                for _ in 0..n {
                    v.push(read_li32(r)?);
                }
                v
            })
        })()
        .map_err(|e| e.at("BiomeCappedSurface.ceiling_blocks"))?;
        let f_sea_block = (|| -> Result<_> {
            Ok(if read_bool(r)? {
                Some(read_lu32(r)?)
            } else {
                None
            })
        })()
        .map_err(|e| e.at("BiomeCappedSurface.sea_block"))?;
        let f_foundation_block = (|| -> Result<_> {
            Ok(if read_bool(r)? {
                Some(read_lu32(r)?)
            } else {
                None
            })
        })()
        .map_err(|e| e.at("BiomeCappedSurface.foundation_block"))?;
        let f_beach_block = (|| -> Result<_> {
            Ok(if read_bool(r)? {
                Some(read_lu32(r)?)
            } else {
                None
            })
        })()
        .map_err(|e| e.at("BiomeCappedSurface.beach_block"))?;
        Ok(Self {
            floor_blocks: f_floor_blocks,
            ceiling_blocks: f_ceiling_blocks,
            sea_block: f_sea_block,
            foundation_block: f_foundation_block,
            beach_block: f_beach_block,
        })
    }
    pub fn write(&self, w: &mut BytesMut) {
        write_varint(w, self.floor_blocks.len() as u32);
        for x0 in self.floor_blocks.iter() {
            write_li32(w, *x0);
        }
        write_varint(w, self.ceiling_blocks.len() as u32);
        for x0 in self.ceiling_blocks.iter() {
            write_li32(w, *x0);
        }
        match &self.sea_block {
            Some(x0) => {
                write_bool(w, true);
                write_lu32(w, *x0);
            }
            None => write_bool(w, false),
        }
        match &self.foundation_block {
            Some(x0) => {
                write_bool(w, true);
                write_lu32(w, *x0);
            }
            None => write_bool(w, false),
        }
        match &self.beach_block {
            Some(x0) => {
                write_bool(w, true);
                write_lu32(w, *x0);
            }
            None => write_bool(w, false),
        }
    }
}

